	@Test
	void routineRefreshKeepsServingTheValidValueAndPublishesAtomically() throws Exception {
		AtomicInteger computations = new AtomicInteger();
		CountDownLatch refreshStarted = new CountDownLatch(1);
		CountDownLatch releaseRefresh = new CountDownLatch(1);
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		LmdbStatementPatternCardinalityCache cache = asynchronousCache((key, multiplier) -> {
			if (computations.incrementAndGet() == 2) {
				assertEquals(4, multiplier);
				refreshStarted.countDown();
				await(releaseRefresh);
				return 20.0d;
			}
			assertEquals(1, multiplier);
			return 10.0d;
		}, () -> 100L, executor);
		try {
			LmdbStatementPatternCardinalityCache.Key key = promote(cache, "serve-during-refresh");
			cache.requestRefresh();
			assertTrue(refreshStarted.await(5, TimeUnit.SECONDS));

			assertEquals(10.0d, cache.estimate(key), "A routine refresh must not hide a valid value");
			releaseRefresh.countDown();
			cache.stopRefreshAndDrain();

			assertEquals(20.0d, cache.estimate(key), "The rich estimate should publish as one atomic replacement");
		} finally {
			releaseRefresh.countDown();
			cache.stopRefreshAndDrain();
			executor.shutdownNow();
		}
	}

	@Test
	void invalidationPreventsAnOlderRefreshFromPublishing(@TempDir Path tempDir) throws Exception {
		AtomicInteger computations = new AtomicInteger();
		List<Integer> multipliers = new ArrayList<>();
		AtomicLong now = new AtomicLong(100L);
		CountDownLatch refreshStarted = new CountDownLatch(1);
		CountDownLatch releaseRefresh = new CountDownLatch(1);
		ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		LmdbStatementPatternCardinalityCache.Config config = new LmdbStatementPatternCardinalityCache.Config(
				8, 1_000L, 0.01d, 2, 0L, 1, 3, 100L, 0L, 100L, 4);
		Path sidecar = tempDir.resolve("cardinality.bin");
		TestCodec codec = new TestCodec();
		LmdbStatementPatternCardinalityCache.Key key = key("invalidate-during-refresh");
		codec.register(46L, key.predicate());
		LmdbStatementPatternCardinalityCache cache = new LmdbStatementPatternCardinalityCache(config,
				(ignored, multiplier) -> {
					multipliers.add(multiplier);
					int computation = computations.incrementAndGet();
					if (computation == 2) {
						refreshStarted.countDown();
						await(releaseRefresh);
						return 20.0d;
					}
					return computation == 1 ? 10.0d : 30.0d;
				}, () -> 100L, () -> 7L, codec, sidecar, executor, now::get);
		try {
			promote(cache, "invalidate-during-refresh");
			cache.requestRefresh();
			assertTrue(refreshStarted.await(5, TimeUnit.SECONDS));

			cache.recordCommittedMutations(2L, 0L);
			assertEquals(30.0d, cache.estimate(key),
					"Foreground recovery must synchronously use the normal budget after invalidation");
			releaseRefresh.countDown();
			cache.stopRefreshAndDrain();

			assertEquals(30.0d, cache.estimate(key), "A pre-invalidation rich result must never publish");
			assertEquals(List.of(1, 4, 1), multipliers);
			cache.persist();

			LmdbStatementPatternCardinalityCache reopened = persistentCache(config,
					(ignored, multiplier) -> 40.0d, () -> 100L, () -> 7L, codec, sidecar, now);
			assertEquals(30.0d, reopened.estimate(key),
					"A stale rich result must not become valid again through a matching restart snapshot");
		} finally {
			releaseRefresh.countDown();
			cache.stopRefreshAndDrain();
			executor.shutdownNow();
		}
	}

	@Test
	void shutdownDrainsARunningRefreshBeforeReturning() throws Exception {
		CountDownLatch refreshStarted = new CountDownLatch(1);
		CountDownLatch releaseRefresh = new CountDownLatch(1);
		CountDownLatch stopReturned = new CountDownLatch(1);
		ScheduledExecutorService maintenance = Executors.newSingleThreadScheduledExecutor();
		ExecutorService stopper = Executors.newSingleThreadExecutor();
		LmdbStatementPatternCardinalityCache cache = asynchronousCache((key, multiplier) -> {
			if (multiplier == 4) {
				refreshStarted.countDown();
				await(releaseRefresh);
			}
			return 10.0d;
		}, () -> 100L, maintenance);
		try {
			promote(cache, "drain-refresh");
			cache.requestRefresh();
			assertTrue(refreshStarted.await(5, TimeUnit.SECONDS));
			stopper.submit(() -> {
				cache.stopRefreshAndDrain();
				stopReturned.countDown();
			});

			assertFalse(stopReturned.await(100, TimeUnit.MILLISECONDS),
					"Shutdown must remain blocked while the estimator is still refreshing");
			releaseRefresh.countDown();
			assertTrue(stopReturned.await(5, TimeUnit.SECONDS));
		} finally {
			releaseRefresh.countDown();
			cache.stopRefreshAndDrain();
			stopper.shutdownNow();
			maintenance.shutdownNow();
		}
	}

